id: org.club.chains
version: 1
name: Chains
lang: en
teams: [red, blue]
squads: 2
reveal: active
disclosure: leader
nodes:
  n1: { role: objective }
  n2: { role: objective }
  n3: { role: objective }
  n4: { role: objective }
objectives:
  - { id: a1, name: Alpha one, type: capture_and_hold, target: n1, assignee: { team: red, squad: 1 } }
  - { id: a2, name: Alpha two, type: capture_and_hold, target: n2, assignee: { team: red, squad: 1 }, depends_on: [a1] }
  - { id: a3, name: Alpha three, type: capture_and_hold, target: n3, assignee: { team: red, squad: 1 }, depends_on: [a2] }
  - { id: b1, name: Bravo one, type: capture_and_hold, target: n4, assignee: { team: red, squad: 2 } }

